 end endtask
 task check(input string id,input bit ok,input string detail);
 begin
  checks=checks+1;
  $display("CHECK %s %s %s",id,ok?"PASS":"FAIL",detail);
  if(!ok) failures=failures+1;
 end endtask
 task pulse(output reg read_bit);
