gold g(.SCK(SCK),.RST_N(RST_N),.MOSI(MOSI),.NORM_CS_N(NORM_CS_N),.START(START),.ENC_DEC(ENC_DEC),.MISO(gm),.BUSY(gb),.ICE_LED(gl));
gate t(.SCK(SCK),.RST_N(RST_N),.MOSI(MOSI),.NORM_CS_N(NORM_CS_N),.START(START),.ENC_DEC(ENC_DEC),.MISO(tm),.BUSY(tb),.ICE_LED(tl));
