 if isinstance(v,str):return v
 if isinstance(v,list):return '\n'.join(x.get('text','') for x in v if isinstance(x,dict) and x.get('type') in ['text','input_text','output_text'])
 return ''
for no,raw in enumerate(lines,1):
 d=json.loads(raw);q=d.get('payload',{});kind=d.get('type');stamp=d.get('timestamp')
 if kind=='session_meta':
