 if kind=='event_msg' and q.get('type')=='task_started':
  turn_id=q['turn_id'];turns.append({'turn_id':turn_id,'started_timestamp':stamp,'delegated_prompts':0,'commentaries':0,'finals':0})
 if kind=='event_msg' and q.get('type')=='task_complete':
  for t in turns:
   if t['turn_id']==q['turn_id']:t['completed_timestamp']=stamp
 if kind=='turn_context':contexts.append({'source_line':no,'timestamp':stamp,**{k:q.get(k) for k in ['turn_id','model','effort']}})
 if kind=='compacted':compactions.append({'source_line':no,'timestamp':stamp,'note':'Internal compaction payload omitted; earlier chronological visible records retained.'})
 payload=None;category=None
 if kind=='response_item':
  qt=q.get('type')
  if qt=='message' and q.get('role') in ['user','assistant']:
   if q.get('role')=='user' or (q.get('phase') in ['commentary','final_answer'] and q.get('channel')!='analysis'):
    payload={k:q[k] for k in ['type','id','role','content','phase','channel'] if k in q}
    category='user_role_message' if q['role']=='user' else 'assistant_'+q['phase']
  elif qt in ['function_call','custom_tool_call','function_call_output','custom_tool_call_output']:
   payload={k:q[k] for k in ['type','id','status','call_id','name','namespace','arguments','input','output'] if k in q};category=qt
   if qt=='function_call_output' and isinstance(q.get('output'),str) and '<codex_delegation>' in q['output']:category='delegated_task'
  else:excluded['response_item:'+str(qt)]+=1
 elif kind=='event_msg' and q.get('type')=='item_completed':
  item=q.get('item',{})
  if item.get('type')=='CommandExecution':
   payload={'type':'command_execution',**{k:item[k] for k in ['id','process_id','command','cwd','source','status','aggregated_output','exit_code','duration'] if k in item},'started_at_ms':q.get('started_at_ms'),'completed_at_ms':q.get('completed_at_ms')};category='command_execution'
