 'all_observed_turns_have_one_prompt_and_final':all(t['delegated_prompts']==1 and t['finals']==1 for t in turns),
 'scope':'All available visible response records, delegated task envelopes and command execution records in this clean native session snapshot.',
 'limits':['Filtered user-visible export, not an unabridged native session file.','Internal reasoning, system/developer instructions, compaction replacement context and unrelated chat content are excluded.','Tool outputs may already have been truncated by the original tools; full experiment files remain separately preserved.','Configured model labels do not authenticate serving weights or missing inference parameters.','The coordinating source chat was identified by metadata only; its earlier mixed history was not read or exported.','No share link created; export remains local.']}
(DEST/'export_manifest.json').write_text(json.dumps(summary,indent=2)+'\n')
for record in events:
 q=json.loads(lines[record['source_line']-1])['payload']
 if record['category']=='command_execution':
  item=q['item'];assert all(record['payload'][k]==item[k] for k in ['command','cwd','aggregated_output','exit_code','status'] if k in item)
 else:assert all(q[k]==v for k,v in record['payload'].items())
(DEST/'field_integrity_verification.json').write_text(json.dumps({'pass':True,'records_verified':len(events),'method':'Every exported message/tool field equals its authentic native source field; raw source-line digests retained.'},indent=2)+'\n')
print(json.dumps({'turns':len(turns),'counts':dict(counts),'all_prompts_and_finals_present':summary['all_observed_turns_have_one_prompt_and_final'],'destination':str(DEST)},indent=2))

